}{% elsif vlm_color_name contains 'grey' or vlm_color_name contains 'gray' %}{% assign vlm_fallback = '#9b9b98' %}{% elsif vlm_color_name contains 'navy' %}{% assign vlm_fallback = '#243044' %}{% elsif vlm_color_name contains 'sand' or vlm_color_name contains 'beige' %}{% assign vlm_fallback = '#d5c3a2' %}{% endif %}<button type="button" class="vlm-gp-swatch{% if forloop.first %} is-active{% endif %}" data-vlm-color-swatch data-image="{% if vlm_variant.featured_image %}{{ vlm_variant.featured_image | image_url: width: 900 }}{% endif %}" data-url="{{ vlm_product.url }}?variant={{ vlm_variant.id }}" aria-label="{{ vlm_color.name | escape }}" aria-pressed="{% if forloop.first %}true{% else %}false{% endif %}" title="{{ vlm_color.name | escape }}">{% if vlm_color.swatch.image %}<img src="{{ vlm_color.swatch.image | image_url: width: 64 }}" alt="" width="64" height="64" loading="lazy">{% else %}<span style="background-color:{% if vlm_color.swatch.color %}{{ vlm_color.swatch.color }}{% else %}{{ vlm_fallback }}{% endif %}"></span>{% endif %}</button>{% endfor %}</div>{% endif %}{% endfor %}<div class="vlm-gp-prices"><span>{{ vlm_product.price | money_with_currency }}</span>{% if vlm_product.compare_at_price > vlm_product.price %}<s>{{ vlm_product.compare_at_price | money }}</s>{% endif %}</div>{% if vlm_collection.handle == 'final-sale' %}<a class="vlm-gp-explore nm-fs-card-cta" href="{{ vlm_product.url }}" data-nm-track="choose_size">Choose size →</a>{% else %}<a class="vlm-gp-explore" href="{{ vlm_product.url }}">{% case request.locale.iso_code %}{% when 'de' %}Entdecken{% when 'es' %}Explorar{% when 'fr' %}Découvrir{% else %}Explore{% endcase %}</a>{% endif %}</div></article>
